using PaymentService.Application;
using PaymentService.Contracts;
namespace PaymentService.Api; public static class Endpoints { public static void MapPaymentEndpoints(this WebApplication app) { app.MapGet("/manage/health", () => Results.Ok(new { status = "UP" })); app.MapPost("/internal/payments", async (CreatePaymentDto d, PaymentApplication s, CancellationToken ct) => Results.Ok(await s.CreateAsync(d.Price, ct))); app.MapGet("/internal/payments/{uid:guid}", async (Guid uid, PaymentApplication s, CancellationToken ct) => await s.GetAsync(uid, ct) is { } x ? Results.Ok(x) : Results.NotFound(new ErrorDto("Payment not found"))); app.MapDelete("/internal/payments/{uid:guid}", async (Guid uid, PaymentApplication s, CancellationToken ct) => await s.CancelAsync(uid, ct) ? Results.NoContent() : Results.NotFound(new ErrorDto("Payment not found"))); } }
